        open: function () {
            const element = this.element;

            element.addClass("open");

            this._fireEvent("open");
        },

        close: function () {
            const element = this.element;

            element.removeClass("open");

            this._fireEvent("close");
        },

        toggle: function () {
            const element = this.element;

            if (element.hasClass("open") === true) {
                this.close();
            } else {
                this.open();
            }

            this._fireEvent("toggle");
        },

