((Metro, $) => {

    let GravatarDefaultConfig = {
        gravatarDeferred: 0,
        email: "",
        size: 80,
        default: "mp",
        onGravatarCreate: Metro.noop,
    };

    Metro.gravatarSetup = (options) => {
        GravatarDefaultConfig = $.extend({}, GravatarDefaultConfig, options);
    };

    if (typeof globalThis.metroGravatarSetup !== "undefined") {
        Metro.gravatarSetup(globalThis.metroGravatarSetup);
    }

    Metro.Component("gravatar", {
        init: function (options, elem) {
            this._super(elem, options, GravatarDefaultConfig);

            return this;
        },

        _create: function () {
            const element = this.element;

            this.get();

            this._fireEvent("gravatar-create", {
                element: element,
            });
        },

        getImage: function (email, size, def, is_object) {
            const image = $("<img>").attr("alt", email);

            image.attr("src", this.getImageSrc(email, size));

            return is_object === true ? image : image[0];
        },

        getImageSrc: (email, size = 80, def = "404") => {
            if (email === undefined || email.trim() === "") {
                return "";
            }

            return `https://www.gravatar.com/avatar/${Metro.md5(email.toLowerCase().trim())}?size=${size}&d=${Metro.utils.encodeURI(def)}`;
        },

        get: function () {
            const element = this.element;
            const o = this.options;
            const img = element[0].tagName === "IMG" ? element : element.find("img");

            if (img.length === 0) {
                return;
            }
            img.attr("src", this.getImageSrc(o.email, o.size, o.default));

            return this;
        },

        resize: function (new_size) {
            this.options.size = new_size !== undefined ? new_size : this.element.attr("data-size");
            this.get();
        },

        email: function (new_email) {
            this.options.email = new_email !== undefined ? new_email : this.element.attr("data-email");
            this.get();
        },

        changeAttribute: function (attributeName) {
            switch (attributeName) {
                case "data-size":
                    this.resize();
                    break;
                case "data-email":
                    this.email();
                    break;
            }
        },

        destroy: function () {
            return this.element;
        },
    });
})(Metro, Dom);

((Metro, $) => {

    let HintDefaultConfig = {
        hintDeferred: 0,
        hintHide: 5000,
        clsHint: "",
        hintText: "",
        hintPosition: Metro.position.TOP,
        hintOffset: 4,
        onHintShow: Metro.noop,
        onHintHide: Metro.noop,
        onHintCreate: Metro.noop,
    };

    Metro.hintSetup = (options) => {
        HintDefaultConfig = $.extend({}, HintDefaultConfig, options);
    };

    if (typeof globalThis.metroHintSetup !== "undefined") {
        Metro.hintSetup(globalThis.metroHintSetup);
    }

    Metro.Component("hint", {
        init: function (options, elem) {
            this._super(elem, options, HintDefaultConfig, {
                hint: null,
                hint_size: {
                    width: 0,
                    height: 0,
                },
                id: null,
            });

            return this;
        },

        _create: function () {
            this.id = Hooks.useId(this.element);
            this._createEvents();
            this._fireEvent("hint-create", {
                element: this.element,
            });
        },

        _createEvents: function () {
            const element = this.element;
            const o = this.options;
            let over = false;

            element.on(Metro.events.enter, () => {
                over = true;
                setTimeout(() => {
                    if (!over) return;

                    this.createHint();
                    if (+o.hintHide > 0) {
                        setTimeout(() => {
                            this.removeHint();
                        }, o.hintHide);
                    }
                }, o.hintDeferred);
            });

            element.on(Metro.events.leave, () => {
                over = false;
                this.removeHint();
            });

            $(globalThis).on(
                `${Metro.events.scroll} ${Metro.events.resize}`,
                () => {
                    if (this.hint !== null) this.setPosition();
                },
                { ns: this.id },
            );
        },

        createHint: function () {
            const elem = this.elem;
            const element = this.element;
            const o = this.options;
            const hint = $("<div>").addClass("hint").addClass(o.clsHint).html(o.hintText);

            this.hint = hint;
            this.hint_size = Metro.utils.hiddenElementSize(hint);

            $(".hint:not(.permanent-hint)").remove();

            if (elem.tagName === "TD" || elem.tagName === "TH") {
                const wrp = $("<div/>").css("display", "inline-block").html(element.html());
                element.html(wrp);
                this.element = wrp;
            }

            this.setPosition();

            hint.appendTo($("body"));

            this._fireEvent("hint-show", {
                hint: hint[0],
            });
        },

        setPosition: function () {
            const hint = this.hint;
            const hint_size = this.hint_size;
            const o = this.options;
            const element = this.element;

            if (o.hintPosition === Metro.position.BOTTOM) {
                hint.addClass("bottom");
                hint.css({
                    top: element.offset().top - $(globalThis).scrollTop() + element.outerHeight() + o.hintOffset,
                    left:
                        element.offset().left +
                        element.outerWidth() / 2 -
                        hint_size.width / 2 -
                        $(globalThis).scrollLeft(),
                });
            } else if (o.hintPosition === Metro.position.RIGHT) {
                hint.addClass("right");
                hint.css({
                    top:
                        element.offset().top +
                        element.outerHeight() / 2 -
                        hint_size.height / 2 -
                        $(globalThis).scrollTop(),
                    left: element.offset().left + element.outerWidth() - $(globalThis).scrollLeft() + o.hintOffset,
                });
            } else if (o.hintPosition === Metro.position.LEFT) {
                hint.addClass("left");
                hint.css({
                    top:
                        element.offset().top +
                        element.outerHeight() / 2 -
                        hint_size.height / 2 -
                        $(globalThis).scrollTop(),
                    left: element.offset().left - hint_size.width - $(globalThis).scrollLeft() - o.hintOffset,
                });
            } else {
                hint.addClass("top");
                hint.css({
                    top: element.offset().top - $(globalThis).scrollTop() - hint_size.height - o.hintOffset,
                    left:
                        element.offset().left -
                        $(globalThis).scrollLeft() +
                        element.outerWidth() / 2 -
                        hint_size.width / 2,
                });
            }
        },

        removeHint: function () {
            const hint = this.hint;
            const options = this.options;
            const timeout = options.onHintHide === Metro.noop ? 0 : 300;

            if (hint !== null) {
                this._fireEvent("hint-hide", {
                    hint: hint[0],
                });

                setTimeout(() => {
                    hint.hide(0, () => {
                        hint.remove();
                        this.hint = null;
                    });
                }, timeout);
            }
        },

        changeText: function () {
            this.options.hintText = this.element.attr("data-hint-text");
        },

        changeAttribute: function (attributeName) {
            if (attributeName === "data-hint-text") {
                this.changeText();
            }
        },

        destroy: function () {
            const element = this.element;
            this.removeHint();
            element.off(`${Metro.events.enter}-hint`);
            element.off(`${Metro.events.leave}-hint`);
            $(globalThis).off(`${Metro.events.scroll}-hint`);
        },
    });
})(Metro, Dom);

