((Metro, $) => {

    let RatingDefaultConfig = {
        ratingDeferred: 0,
        label: "",
        static: false,
        title: null,
        value: 0,
        values: null,
        message: "",
        stars: 5,
        onColor: null,
        offColor: null,
        roundFunc: "round", // ceil, floor, round
        half: true,
        symbol: "★",
        clsRating: "",
        clsTitle: "",
        clsStars: "",
        clsResult: "",
        clsLabel: "",
        onStarClick: Metro.noop,
        onRatingCreate: Metro.noop,
    };

    Metro.ratingSetup = (options) => {
        RatingDefaultConfig = $.extend({}, RatingDefaultConfig, options);
    };

    if (typeof globalThis.metroRatingSetup !== "undefined") {
        Metro.ratingSetup(globalThis.metroRatingSetup);
    }

    Metro.Component("rating", {
        init: function (options, elem) {
            this._super(elem, options, RatingDefaultConfig, {
                value: 0,
                originValue: 0,
                values: [],
                rate: 0,
                rating: null,
            });

            return this;
        },

        _create: function () {
            const element = this.element;
            const o = this.options;
            let i;

            if (Number.isNaN(o.value)) {
                o.value = 0;
            } else {
                o.value = Number.parseFloat(o.value).toFixed(1);
            }

            if (o.values !== null) {
                if (Array.isArray(o.values)) {
                    this.values = o.values;
                } else if (typeof o.values === "string") {
                    this.values = o.values.toArray();
                }
            } else {
                for (i = 1; i <= o.stars; i++) {
                    this.values.push(i);
                }
            }

            this.originValue = o.value;
            this.value = o.value > 0 && o.roundFunc !== "none" ? Math[o.roundFunc](o.value) : Math.abs(o.value);

            this._createRating();
            this._createEvents();

            this._fireEvent("rating-create", {
                element: element,
            });
        },

        _createRating: function () {
            const element = this.element;
            const o = this.options;

            let i;
            let stars;
            let li;
            const sheet = Metro.sheet;
            const value = o.static ? Math.floor(this.originValue) : this.value;

            const rating = element.wrap("<div>").addClass(`rating ${element[0].className}`).addClass(o.clsRating);
            const id = Hooks.useId(rating[0]);

            element.val(this.value);

            rating.attr("id", element.id() ? `rating--${element.id()}` : id);

            stars = $("<ul>").addClass("stars").addClass(o.clsStars).appendTo(rating);

            for (i = 1; i <= o.stars; i++) {
                li = $("<li>")
                    .attr("data-symbol", o.symbol)
                    .data("value", this.values[i - 1])
                    .appendTo(stars);
                if (i <= value) {
                    li.addClass("on");
                }
            }

            const result = $("<span>").addClass("result").addClass(o.clsResult).appendTo(rating);
            result.html(o.message);

            if (o.offColor !== null && (o.offColor.includes("var(") || Farbe.Routines.isColor(o.offColor))) ;

            if (o.onColor !== null && (o.onColor.includes("var(") || Farbe.Routines.isColor(o.onColor))) {
                Metro.utils.addCssRule(sheet, `#${id} .stars:hover li`, `color: ${o.onColor};`);
                Metro.utils.addCssRule(sheet, `#${id} .stars li.on`, `color: ${o.onColor};`);
                Metro.utils.addCssRule(sheet, `#${id} .stars li.half::after`, `color: ${o.onColor};`);
            }

            if (o.title !== null) {
                const title = $("<span>").addClass("title").addClass(o.clsTitle).html(o.title);
                rating.prepend(title);
            }

            if (o.static === true) {
                rating.addClass("static");
                if (o.half === true) {
                    const dec = Math.round((this.originValue % 1) * 10);
                    if (dec > 0 && dec <= 9) {
                        rating
                            .find(".stars li.on")
                            .last()
                            .next("li")
                            .addClass(`half half-${dec * 10}`);
                    }
                }
            }

            element[0].className = "";

            if (o.label) {
                const label = $("<label>")
                    .addClass("label-for-input")
                    .addClass(o.clsLabel)
                    .html(o.label)
                    .insertBefore(rating);
                if (element.attr("id")) {
                    label.attr("for", element.attr("id"));
                } else {
                    const id = Hooks.useId(element[0]);
                    label.attr("for", id);
                    element.attr("id", id);
                }
                if (element.attr("dir") === "rtl") {
                    label.addClass("rtl");
                }
            }

            if (element.is(":disabled")) {
                this.disable();
            } else {
                this.enable();
            }

            this.rating = rating;
        },

        _createEvents: function () {
            const that = this;
            const element = this.element;
            const o = this.options;
            const rating = this.rating;

            rating.on(Metro.events.click, ".stars li", function () {
                if (o.static === true) {
                    return;
                }

                const star = $(this);
                const value = star.data("value");
                star.addClass("scale");
                setTimeout(() => {
                    star.removeClass("scale");
                }, 300);
                element.val(value).trigger("change");
                star.addClass("on");
                star.prevAll().addClass("on");
                star.nextAll().removeClass("on");

                that._fireEvent("star-click", {
                    value: value,
                    star: star[0],
                });
            });
        },

        val: function (v) {
            const that = this;
            const element = this.element;
            const o = this.options;
            const rating = this.rating;

            if (v === undefined) {
                return this.value;
            }

            this.value = v > 0 ? Math[o.roundFunc](v) : 0;
            element.val(this.value).trigger("change");

            const stars = rating.find(".stars li").removeClass("on");
            $.each(stars, function () {
                const star = $(this);
                if (star.data("value") <= that.value) {
                    star.addClass("on");
                }
            });

            return this;
        },

        msg: function (m) {
            const rating = this.rating;
            if (m === undefined) {
                return;
            }
            rating.find(".result").html(m);
            return this;
        },

        static: function (mode) {
            const o = this.options;
            const rating = this.rating;

            o.static = mode;

            if (mode === true) {
                rating.addClass("static");
            } else {
                rating.removeClass("static");
            }
        },

        changeAttributeStatic: function () {
            const element = this.element;
            const isStatic = JSON.parse(element.attr("data-static")) === true;

            this.static(isStatic);
        },

        disable: function () {
            this.element.data("disabled", true);
            this.element.parent().addClass("disabled");
        },

        enable: function () {
            this.element.data("disabled", false);
            this.element.parent().removeClass("disabled");
        },

        toggleState: function () {
            if (this.elem.disabled) {
                this.disable();
            } else {
                this.enable();
            }
        },

        changeAttribute: function (attributeName, value) {
            switch (attributeName) {
                case "value":
                case "data-value":
                    this.val(value);
                    break;
                case "disabled":
                    this.toggleState();
                    break;
                case "data-message":
                    this.msg(value);
                    break;
                case "data-static":
                    this.changeAttributeStatic();
                    break;
            }
        },

        destroy: function () {
            const o = this.options;
            const rating = this.rating;

            rating.off(Metro.events.click, ".stars li");

            if (o.label) {
                rating.prev("label").remove();
            }
            rating.remove();
        },
    });
})(Metro, Dom);

((Metro, $) => {

    let RemoteDatasetDefaultConfig = {
        caption: "",
        url: "",
        searchUrl: "",
        method: "GET",
        limit: 10,
        offset: 0,
        sort: "",
        limitKey: "limit",
        offsetKey: "offset",
        searchKey: "query",
        totalKey: "total",
        dataKey: "data",
        sortKey: "sortBy",
        orderKey: "order",
        shortPagination: false,
        rows: 10,
        rowsSteps: "10,25,50,100",
        sortRules: "",

        showSearch: true,
        showOrder: true,
        showRowsCount: true,

        template: "",

        clsBody: "",
        clsItem: "",
        clsPagination: "",
        clsSearchBlock: "",
        clsOrderBlock: "",
        clsRowsCountBlock: "",

        onLoad: (f) => f,
        onDrawRow: Metro.noop,
        onDrawCell: Metro.noop,
        onDatasetCreate: Metro.noop,
    };

    Metro.remoteDatasetSetup = (options) => {
        RemoteDatasetDefaultConfig = $.extend({}, RemoteDatasetDefaultConfig, options);
    };

    if (typeof globalThis.metroRemoteDatasetSetup !== "undefined") {
        Metro.remoteDatasetSetup(globalThis.metroRemoteDatasetSetup);
    }

    Metro.Component("remote-dataset", {
        init: function (options, elem) {
            this._super(elem, options, RemoteDatasetDefaultConfig, {
                // define instance vars here
                data: null,
                total: 0,
            });
            return this;
        },

        _create: function () {
            const o = this.options;

            this.offset = o.offset;
            this.rowSteps = o.rowsSteps.toArray(",");
            this.limit = +o.rows;
            this.url = o.url;
            this.search = "";
            const [field, order] = o.sort.toArray(":");
            this.sortField = field;
            this.sortOrder = order;
            this.template = Metro.utils.exec(o.template);
            this.sortRules = o.sortRules
                .toArray(",")
                .filter((f) => f)
                .map((rule) => rule.toArray(":"));
            this._createStructure();
            this._createEvents();

            this._loadData().then(() => {});

            this._fireEvent("dataset-create");
        },

        _loadData: async function (append = false) {
            const o = this.options;
            if (!this.url) {
                return;
            }
            let url = `${this.url}?${o.limitKey}=${this.limit}&${o.offsetKey}=${this.offset}`;
            if (this.sortField) {
                url += `&${o.sortKey}=${this.sortField}&${o.orderKey}=${this.sortOrder}`;
            }
            if (this.search) {
                url += `&${o.searchKey}=${this.search}`;
            }
            const response = await fetch(url, { method: o.method });
            if (response.ok === false) {
                return;
            }
            this.data = Metro.utils.exec(o.onLoad, [await response.json()], this);
            this._createEntries(append);
        },

        _createStructure: function () {
            const element = this.element;
            const o = this.options;
            const entries = $("<div>").addClass("dataset-entry");

            element.addClass("remote-dataset");
            element.append(entries);

            entries.html(`
                <div class="service-block">
                    <div class="search-block ${o.clsSearchBlock} ${o.showSearch ? "" : "hide-block"}">
                        <input name="search" type="text" data-role="input" 
                            data-prepend="${this.strings.label_search}" 
                            data-search-button="true" 
                            />
                    </div>
                   
                    <div class="order-block ${o.clsOrderBlock} ${this.sortRules.length === 0 || o.showOrder === false ? "hide-block" : ""}">
                        <select name="sort-order" data-role="select" data-filter="false">
                            ${this.sortRules
                                .map(
                                    (rule) => `
                                <option value="${rule[0]}:${rule[1]}" 
                                        ${rule[0] === this.sortField && rule[1] === this.sortOrder ? "selected" : ""}
                                        data-icon="${rule[3] ? rule[3] : ""}"
                                >
                                    ${rule[2]}
                                </option>
                            `,
                                )
                                .join("")}
                        </select>
                    </div>
                   
                    <div class="count-block ${o.clsRowsCountBlock} ${o.showRowsCount ? "" : "hide-block"}">
                        <select name="rows-count" data-role="select" data-prepend="${this.strings.label_rows_count}" data-filter="false">
                            ${this.rowSteps
                                .map(
                                    (step) => `
                                <option value="${step}" ${+step === this.rowsCount ? "selected" : ""}>
                                    ${step}
                                </option>
                            `,
                                )
                                .join("")}
                        </select>
                    </div>
                </div>
                <div class="dataset-body"></div>
            `);
            this.body = entries.find(".dataset-body").addClass(o.clsBody);

            this.loadMore = $("<div>").addClass("dataset-load-more");
            this.loadMore
                .html(`
                <button class="button large cycle link load-more-button">
                    <span class="icon">⟳</span>
                    ${this.strings.label_load_more}
                </button>
            `)
                .appendTo(element);

            this.pagination = $("<div>").addClass("dataset-pagination");
            element.append(this.pagination);
        },

        _createEvents: function () {
            const that = this;
            const element = this.element;
            const o = this.options;

            element.on("click", ".page-link", function () {
                const parent = $(this).parent();
                if (parent.hasClass("service")) {
                    if (parent.hasClass("prev-page")) {
                        that.offset -= that.limit;
                        if (that.offset < 0) {
                            that.offset = 0;
                        }
                    } else {
                        that.offset += that.limit;
                    }
                    that._loadData().then(() => {});
                    return;
                }
                that.offset = $(this).data("page") * that.limit - that.limit;
                that._loadData().then(() => {});
            });

            const searchFn = Hooks.useDebounce(() => {
                const val = element.find("input[name=search]").val().trim();
                if (val === "") {
                    this.search = "";
                    this.url = o.url;
                    this._loadData().then(() => {});
                    return;
                }
                if (val.length < 3) {
                    return;
                }
                this.search = val;
                this.url = o.searchUrl;
                this._loadData().then(() => {});
            }, 300);

            element.on(Metro.events.inputchange, "input[name=search]", searchFn);

            element.on("change", "select[name=rows-count]", function () {
                that.limit = +$(this).val();
                that.offset = 0;
                that._loadData().then(() => {});
            });

            element.on("change", "select[name=sort-order]", function () {
                const [field, order] = $(this).val().split(":");
                that.url = o.url;
                that.sortField = field;
                that.sortOrder = order;
                that.offset = 0;
                that._loadData().then(() => {});
            });

            element.on("click", ".load-more-button", () => {
                that.offset += that.limit;
                that._loadData(true).then(() => {});
            });
        },

        _createEntries: function (append = false) {
            const o = this.options;

            if (!this.data) {
                return;
            }

            const usePagination = Metro.utils.isValue(this.data[o.totalKey]);

            this.entries = this.data[o.dataKey];
            this.total = this.data[o.totalKey];

            if (append === false) this.body.clear();

            this.entries.forEach((entry, index) => {
                const item = $("<div>")
                    .addClass("dataset-item")
                    .addClass(o.clsItem)
                    .addClass(index % 2 === 0 ? "even" : "odd");
                const html = Metro.utils.exec(o.template, [entry], entry);
                item.html(html).appendTo(this.body);
            });

            if (usePagination && !o.shortPagination) {
                Metro.pagination({
                    length: this.total,
                    rows: this.limit,
                    current: this.offset === 0 ? 1 : Math.round(this.offset / this.limit) + 1,
                    target: this.pagination,
                    clsPagination: o.clsPagination,
                });
            } else {
                this.pagination.html(`
                    <div class="short-pagination">
                        <div class="button service prev-page"><a href="javascript:void(0)" class="page-link">${this.strings.label_prev}</a></div>
                        <div class="button service next-page"><a href="javascript:void(0)" class="page-link">${this.strings.label_next}</a></div>
                    </div>
                `);
            }
        },

        /*
         * options = {
         *   caption: "",
         *   url: "",
         *   searchUrl: "",
         *   method: "GET",
         *   limit: 10,
         *   offset: 0,
         *   sort: "",
         *   sortOrder: "asc",
         *   limitKey: "limit",
         * }
         * */
        setup: (options) => {},

        changeAttribute: (attr, newValue) => {},

        destroy: function () {
            this.element.remove();
        },
    });
})(Metro, Dom);

