((Metro, $) => {

    let TaskBarDefaultConfig = {
        onTaskClick: Metro.noop,
        onMyObjectCreate: Metro.noop,
    };

    Metro.taskBarSetup = (options) => {
        TaskBarDefaultConfig = $.extend({}, TaskBarDefaultConfig, options);
    };

    if (typeof globalThis.metroTaskBarSetup !== "undefined") {
        Metro.taskBarSetup(globalThis.metroTaskBarSetup);
    }

    Metro.Component("task-bar", {
        init: function (options, elem) {
            this._super(elem, options, TaskBarDefaultConfig, {
                // define instance vars here
                tasks: [],
                systemTray: [],
                widgets: [],
            });
            return this;
        },

        _create: function () {
            this._createStructure();
            this._createEvents();

            this._fireEvent("task-bar-create");
        },

        _createStructure: function () {
            const element = this.element;
            this.options;

            element.addClass("task-bar");
            element.append($("<div>").addClass("widgets"));
            element.append($("<div>").addClass("tasks"));
            element.append($("<div>").addClass("system-tray"));
        },

        _createEvents: function () {
            const that = this;
            const element = this.element;

            element.on(Metro.events.click, ".task", function () {
                const task = that.tasks[$(this).index()];
                for (const t of that.tasks) {
                    t.active = false;
                }
                task.active = true;
                that._renderTasks();
                that._fireEvent("task-click", {
                    task: task,
                    element: task.ref,
                });
            });

            element.on(Metro.events.click, ".system-tray-item", function () {
                const item = that.systemTray[$(this).index()];
                that._fireEvent("system-tray-click", {
                    item,
                });
            });

            element.on(Metro.events.click, ".widget", function () {
                const item = that.widgets[$(this).index()];
                that._fireEvent("widget-click", {
                    item,
                });
            });
        },

        _renderTasks: function () {
            const element = this.element;
            this.options;
            const tasks = element.find(".tasks").clear();

            for (const task of this.tasks) {
                const taskItem = $("<div>").addClass("task").attr("title", task.title).html(task.icon);
                if (task.active) {
                    taskItem.addClass("active");
                }
                tasks.append(taskItem);
            }
        },

        _renderSystemTray: function () {
            const element = this.element;
            const systemTray = element.find(".system-tray").clear();

            for (const item of this.systemTray) {
                systemTray.append($(item).addClass("system-tray-item"));
            }
        },

        _renderWidgets: function () {
            const element = this.element;
            const widgets = element.find(".widgets").clear();

            for (const widget of this.widgets) {
                widgets.append($(widget).addClass("widget"));
            }
        },

        /*
         * task = {
         *   title: "Task title",
         *   description: "Task description",
         *   icon: "<span class='mif-cogs'></span>",
         *   ref: null, // Reference to the element in the DOM
         * }
         * */
        addTask: function (task, active = false) {
            if (active) {
                for (const t of this.tasks) {
                    t.active = false;
                }
            }
            this.tasks.push({ ...task, active });
            this._renderTasks();
        },

        removeTask: function (task) {
            this.tasks = this.tasks.filter((t) => t.ref !== task);
            this._renderTasks();
        },

        activateTask: function (ref) {
            const tasks = this.tasks.filter((t) => t.ref === ref);
            if (tasks.length === 0) {
                return;
            }
            const task = tasks[0];
            for (const t of this.tasks) {
                t.active = false;
            }
            task.active = true;
            this._renderTasks();
        },

        /*
         * item = HTMLElement
         * */
        addToSystemTray: function (item) {
            this.systemTray.push(item);
            this._renderSystemTray();
        },

        /*
         * widget = HTMLElement
         * */
        addWidget: function (widget) {
            this.widgets.push(widget);
            this._renderWidgets();
        },

        changeAttribute: (attr, newValue) => {},

        destroy: function () {
            this.element.remove();
        },
    });
})(Metro, Dom);

/* Deprecated */
((Metro, $) => {

    const Engine = (html, options, conf) => {
        let ReEx;
        let re = "<%(.+?)%>";
        const reExp = /(^( )?(var|if|for|else|switch|case|break|{|}|;))(.*)?/g;
        let code = "with(obj) { var r=[];\n";
        let cursor = 0;
        let result;
        let match;
        const add = (line, js) => {
            js
                ? // biome-ignore lint/suspicious/noAssignInExpressions: <explanation>
                  (code += line.match(reExp) ? `${line}\n` : `r.push(${line});\n`)
                : // biome-ignore lint/suspicious/noAssignInExpressions: <explanation>
                  (code += line !== "" ? `r.push("${line.replace(/"/g, '\\"')}");\n` : "");
            return add;
        };

        if (Metro.utils.isValue(conf)) {
            if ($.hasProp(conf, "beginToken")) {
                re = re.replace("<%", conf.beginToken);
            }
            if ($.hasProp(conf, "endToken")) {
                re = re.replace("%>", conf.endToken);
            }
        }

        ReEx = new RegExp(re, "g");
        match = ReEx.exec(html);

        while (match) {
            add(html.slice(cursor, match.index))(match[1], true);
            cursor = match.index + match[0].length;
            match = ReEx.exec(html);
        }
        add(html.substring(cursor, html.length - cursor));
        code = `${code}return r.join(""); }`.replace(/[\r\t\n]/g, " ");
        try {
            result = new Function("obj", code).apply(options, [options]);
        } catch (err) {
            console.error(`'${err.message}'`, " in \n\nCode:\n", code, "\n");
        }
        return result;
    };

    let TemplateDefaultConfig = {
        templateData: null,
        onTemplateCompile: Metro.noop,
        onTemplateCreate: Metro.noop,
    };

    Metro.templateSetup = (options) => {
        TemplateDefaultConfig = $.extend({}, TemplateDefaultConfig, options);
    };

    if (typeof globalThis.metroTemplateSetup !== "undefined") {
        Metro.templateSetup(globalThis.metroTemplateSetup);
    }

    Metro.Component("template", {
        init: function (options, elem) {
            this._super(elem, options, TemplateDefaultConfig, {
                template: null,
                data: {},
            });
            return this;
        },

        _compile: function () {
            const element = this.element;

            const template = this.template
                .replace(/(&lt;%)/gm, "<%")
                .replace(/(%&gt;)/gm, "%>")
                .replace(/(&lt;)/gm, "<")
                .replace(/(&gt;)/gm, ">");
            const compiled = Engine(template, this.data);
            element.html(compiled);

            this._fireEvent("template-compile", {
                template: template,
                compiled: compiled,
                element: element,
            });
        },

        _create: function () {
            const element = this.element;
            const o = this.options;
            this.template = element.html();
            this.data = Metro.utils.isObject(o.templateData) || {};
            this._compile();
            this._fireEvent("template-create", {
                element: element,
            });
        },

        buildWith: function (obj) {
            const data = Metro.utils.isObject(obj);
            if (!data) {
                return;
            }
            this.data = data;
            this._compile();
        },

        changeAttribute: function (a, v) {
            if (a === "data-template-data") {
                this.options.templateData = v;
                this.data = Metro.utils.isObject(v) || {};
                this._compile();
            }
        },

        destroy: function () {
            return this.element;
        },
    });

    Metro.template = Engine;
})(Metro, Dom);

